pub fn f_00026090(this: &mut [u8], esi: u32, edx: u32) {
    wr32(this, 0, esi);
    wr32(this, 4, edx);
    for o in [0x58usize, 0x50, 0x48, 0x40, 0x38, 0x30, 0x28, 0x20, 0x18, 0x10, 8] {
        wr64(this, o, 0);
    }
}

/// parity: P1 @0xe644e size=104
/// Stores edx at +0x60 + 4*(esi-1) for esi in 1..=8 and inserts its low nibble into bits 4, 12, 20, 28 of the dword at +0x84 (esi 1..4) or +0x88 (esi 5..8); returns 1, or 0 for any other esi.
pub fn f_000e644e(this: &mut [u8], esi: u32, edx: u32) -> u8 {
    let idx = esi.wrapping_sub(1);
    if idx > 7 {
        return 0;
    }
    wr32(this, 0x60 + idx as usize * 4, edx);
    if esi <= 4 {
        let cl = idx.wrapping_mul(8).wrapping_add(4);
        let keep = !(0xfu32.wrapping_shl(cl)) & rd32(this, 0x84);
        wr32(this, 0x84, ((edx & 0xf).wrapping_shl(cl)) | keep);
    } else {
        let cl = esi.wrapping_mul(8).wrapping_sub(0x24);
        let keep = !(0xfu32.wrapping_shl(cl)) & rd32(this, 0x88);
        wr32(this, 0x88, ((edx & 0xf).wrapping_shl(cl)) | keep);
    }
    1
}

/// parity: P1 @0x5a594 size=108
/// Switch on edi (jump table at 0x5a5dc with 9 entries for edi 1..=9): 1 -> 2, 2 -> 3, 3 -> 1, 4 and 8 -> (sil << 2), 9 -> 5, everything else (including 5, 6, 7) -> 12.
pub fn f_0005a594(edi: u32, esi: u32) -> u32 {
    match edi {
        1 => 2,
        2 => 3,
        3 => 1,
        4 | 8 => (esi & 0xff) << 2,
        9 => 5,
        _ => 0xc,
    }
}

/// parity: P1 @0x59541 size=109
/// Fills ceil(2*r8d/4) groups of four bytes of dst with (dl, sil, cl, sil) when r9d == 1, else (sil, dl, sil, cl); the count is r8d doubled in 32 bits.
pub fn f_00059541(dst: &mut [u8], esi: u32, edx: u32, ecx: u32, r8d: u32, r9d: u32) {
    let limit = r8d.wrapping_add(r8d);
    let mut k: u32 = 0;
    if r9d == 1 {
        if limit == 0 {
            return;
        }
        loop {
            wr8(dst, k as usize, edx as u8);
            wr8(dst, k as usize + 1, esi as u8);
            wr8(dst, k as usize + 2, ecx as u8);
            wr8(dst, k as usize + 3, esi as u8);
            k = k.wrapping_add(4);
            if k >= limit {
                break;
            }
        }
    } else {
        if limit == 0 {
            return;
        }
        loop {
            wr8(dst, k as usize, esi as u8);
            wr8(dst, k as usize + 1, edx as u8);
            wr8(dst, k as usize + 2, esi as u8);
            wr8(dst, k as usize + 3, ecx as u8);
            k = k.wrapping_add(4);
            if k >= limit {
                break;
            }
        }
    }
}

/// parity: P1 @0xcc285 size=109
/// Returns 1 for the identifiers 0x10294700, 0x10322950, 0x10378800, 0x10478350, 0x10518400, 0x10518450 and the range 0x10646700..=0x10646706 (codec or format identifiers, purpose unknown), else 0.
pub fn f_000cc285(edi: u32) -> u8 {
    match edi {
        0x1029_4700 | 0x1032_2950 | 0x1037_8800 | 0x1047_8350 | 0x1051_8400 | 0x1051_8450 | 0x1064_6700..=0x1064_6706 => 1,
        _ => 0,
    }
}

/// parity: P1 @0x3314e size=110
/// Offset into a small multi-dimensional layout: the extent is the dword at +0, the rank the word at +0x34, strides at +0x24, +0x28, +0x2c, +0x30...; returns -1 when esi >= extent or edx (as a 16-bit dimension index) >= rank, else esi * stride[d] + sum of stride[k] * extent for k < d (k up to 2). The branch "rank == 0" after rank > d >= 1 cannot be taken (unreachable).
pub fn f_0003314e(this: &[u8], esi: u32, edx: u32) -> u32 {
    let ext = rd32(this, 0);
    if ext <= esi {
        return 0xffff_ffff;
    }
    let rank = rd16(this, 0x34) as u32;
    let d = edx & 0xffff;
    if rank <= d {
        return 0xffff_ffff;
    }
    let mut acc: u32 = 0;
    if d != 0 {
        acc = 0;
        if rank != 0 {
            acc = rd32(this, 0x24).wrapping_mul(ext);
        }
        if d >= 2 {
            let mut e = 0;
            if rank >= 2 {
                e = rd32(this, 0x28).wrapping_mul(ext);
            }
            acc = acc.wrapping_add(e);
            if d >= 3 {
                let mut e = 0;
                if rank >= 3 {
                    e = ext.wrapping_mul(rd32(this, 0x2c));
                }
                acc = acc.wrapping_add(e);
            }
        }
    }
    esi.wrapping_mul(rd32(this, 0x24 + d as usize * 4)).wrapping_add(acc)
}

/// parity: P1 @0x676f9 size=111
/// In place: packs esi pixels of three words at stride 8 into dwords at stride 4 with 2-bit and 8-bit fields: ((w2&3)<<28)|((w2<<14)&0xff0000)|((w1&3)<<26)|((w1<<6)&0xff00)|((w0>>2)&0xff)|((w0&3)<<24).
pub fn f_000676f9(px: &mut [u8], esi: u32) {
    if esi == 0 {
        return;
    }
    let mut k: usize = 0;
    loop {
        let w2 = rd16(px, k * 8 + 4) as u32;
        let w1 = rd16(px, k * 8 + 2) as u32;
        let w0 = rd16(px, k * 8) as u32;
        let v = ((w2 & 3) << 28) | ((w2 << 14) & 0xff_0000) | ((w1 & 3) << 26) | ((w1 << 6) & 0xff00) | ((w0 >> 2) & 0xff) | ((w0 & 3) << 24);
        wr32(px, k * 4, v);
        k += 1;
        if esi != k as u32 {
            continue;
        }
        break;
    }
}

/// parity: P1 @0x5c039 size=112
/// For edx groups: v = counter % ecx, placed in the high half (shl 16) or, when r8b is non-zero, byte-swapped into the low half; writes r9d copies of it to dst, then increments the counter dword. Returns edx * r9d * 4 (32 bits). Looks like a test-pattern or interleaved sample generator (guess, low confidence).
pub fn f_0005c039(dst: &mut [u8], counter: &mut [u8], edx: u32, ecx: u32, r8d: u32, r9d: u32) -> u32 {
    let mut count = edx;
    if count != 0 {
        let mut at: usize = 0;
        let mut cur = rd32(counter, 0);
        loop {
            let rem = cur % ecx;
            let v = if (r8d as u8) != 0 {
                rem.swap_bytes() >> 16
            } else {
                rem << 16
            };
            if r9d != 0 {
                for k in 0..r9d as usize {
                    wr32(dst, at + k * 4, v);
                }
                at += r9d as usize * 4;
                cur = rd32(counter, 0);
            }
            cur = cur.wrapping_add(1);
            wr32(counter, 0, cur);
            count -= 1;
            if count == 0 {
                break;
            }
        }
    }
    edx.wrapping_mul(r9d).wrapping_shl(2)
}
